eval("__webpack_require__.r(__webpack_exports__);\n/* harmony export */ __webpack_require__.d(__webpack_exports__, {\n/* harmony export */   xiaohongshuContent: () => (/* binding */ xiaohongshuContent)\n/* harmony export */ });\nconst xiaohongshuContent = [\n    // 洱海相关攻略\n    {\n        id: 1,\n        title: \"大理洱海\\uD83C\\uDF0A\",\n        author: \"喵星人\",\n        content: '绕着洱海跑了大半天，从海西到海东，一半烟火一半远方。洱海海东的\"圣托里尼\"，总带着点地中海的浪漫撞进大理的风里——白墙蓝顶沿着山坡铺开，抬头是苍山雪，低头是洱海波，远处还有渔村的炊烟袅袅。',\n        likes: 43,\n        comments: 3,\n        tags: [\n            \"大理\",\n            \"洱海\",\n            \"去有风的地方\",\n            \"旅行\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211122/cc60d77b3fac3684cbfebc3fdd14b13a/1040g00831l0i7i6m2u2g5p46nrojokig2eocqh0!nd_dft_wlteh_webp_3\",\n        category: \"洱海攻略\"\n    },\n    {\n        id: 2,\n        title: \"环洱海观光巴士1️⃣张票承包大理所有浪漫\",\n        author: \"欢萌旅行\",\n        content: '救命！来大理发现神仙巴士，1 张票直接拿捏环洱海 + 往返交通 + N 种权益，纯纯把旅行成本打下来\\uD83D\\uDCA5。复古红车身超吸睛，车窗超大视野，坐上层前排 = 移动观景台，洱海风光直接 \"框\" 进车窗。',\n        likes: 176,\n        comments: 21,\n        tags: [\n            \"大理\",\n            \"环洱海巴士\",\n            \"云南\",\n            \"旅游攻略\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211122/b0a51fe55e55ff3235e18e4e9de28e65/1040g00831komht1diu3g5omobmhgga1o792g5cg!nd_dft_wlteh_webp_3\",\n        category: \"洱海攻略\"\n    },\n    {\n        id: 3,\n        title: \"\\uD83D\\uDCCD 环洱海一日行程（附真实体验+小tips）\",\n        author: \"SepQ\",\n        content: \"终于去大理玩了！！看了绝美风景，真爽！！由于呆的时间比较短，提前在网上做攻略到头秃！看到好多行程推荐，鉴于本人很懒，看到网上有姐妹发环洱海包车可以省时省事，于是开启一日环海行程，美美享受\\uD83D\\uDC97\",\n        likes: 136,\n        comments: 10,\n        tags: [\n            \"大理\",\n            \"洱海\",\n            \"环海攻略\",\n            \"云南\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211122/a135bd3ffc7c20edee6f5fc5b22e0fd9/1040g00831l0i7i6m2u0g5p46nrojokig12rghvo!nd_dft_wlteh_webp_3\",\n        category: \"洱海攻略\"\n    },\n    {\n        id: 4,\n        title: \"8.3洱海实况图\",\n        author: \"是七七康康哟\",\n        content: \"云南的天气真的不用看天气预报☔️，本来都打算下雨就下雨吧，谁知道暴晒一天\\uD83C\\uDF1E。S湾-廊桥段的生态步道真美，喜洲人真的太多了，特别是坐小火车的，但是闻到了稻香，大米的香气。\",\n        likes: 92,\n        comments: 60,\n        tags: [\n            \"大理\",\n            \"洱海\",\n            \"生态廊道\",\n            \"喜洲\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211122/c75cbf5b1556d6c114284d1d81cb0caa/1040g00831l0i7i6m2u105p46nrojokig0msike0!nd_dft_wlteh_webp_3\",\n        category: \"洱海攻略\"\n    },\n    {\n        id: 5,\n        title: \"是美丽的大理洱海啊！不需要滤镜！\",\n        author: \"冰淇淋&贝贝\",\n        content: \"换个视角看洱海~，无需滤镜的美！不愧是大理呀，海边的风景，在有风的地方。\",\n        likes: 59,\n        comments: 3,\n        tags: [\n            \"大理\",\n            \"洱海\",\n            \"龙龛码头\",\n            \"去有风的地方\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211122/5f8f8888f72651a567992d8e25b1a20b/1040g00831l0i7i6m2u1g5p46nrojokigkbbk1oo!nd_dft_wlteh_webp_3\",\n        category: \"洱海攻略\"\n    },\n    // 玉龙雪山相关攻略\n    {\n        id: 6,\n        title: \"玉龙雪山攻略\",\n        author: \"阿拉斯羊\\uD83D\\uDC0F\",\n        content: \"玉龙雪山大索道需提前七天预约，我没有提前预约只抢到18号16：00的票，如果同伴高返无法成行千万不要网络退票，网络退票会整个团队一起退票。到游客中心去退票。\",\n        likes: 1132,\n        comments: 87,\n        tags: [\n            \"玉龙雪山\",\n            \"丽江\",\n            \"索道攻略\",\n            \"云南\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/c000a34253ea68d6ebf120ec3e0ed2ea/1040g2sg319298qgekua05pf6h6519ed4oduii38!nd_dft_wlteh_webp_3\",\n        category: \"玉龙雪山攻略\"\n    },\n    {\n        id: 7,\n        title: \"一人登顶\\uD83C\\uDFD4️玉龙雪山4680❄️\",\n        author: \"MEI--燕\",\n        content: \"10.17一人登顶玉龙雪山，我是跟团来的所以时间特别紧，到了山脚下海拔已经有3000米左右来，一直很害怕会有严重的高反，但还是在不断的肯定自己给自己加油！几乎没有高反成功登顶\\uD83C\\uDFD4️\",\n        likes: 462,\n        comments: 78,\n        tags: [\n            \"玉龙雪山\",\n            \"登顶\",\n            \"4680\",\n            \"云南\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/3a55a9907d529fb35941f0b1718acec1/1040g2sg31l778pck52e05n6ikt3lnt61uj4i19g!nd_dft_wlteh_webp_3\",\n        category: \"玉龙雪山攻略\"\n    },\n    {\n        id: 8,\n        title: \"关于玉龙雪山的高反，以及注意事项，亲身经历\",\n        author: \"是鸭鸭Ya\",\n        content: \"我们是两人出行，我没有高反，我老公有高反，不是在玉龙雪山没有高反就不会有高反了，我老公高反是从雪山下来，游完了蓝月谷，回酒店开始的，当时在山上时只觉得胸闷头晕，没有在意吸氧。\",\n        likes: 1389,\n        comments: 292,\n        tags: [\n            \"玉龙雪山\",\n            \"高反\",\n            \"注意事项\",\n            \"丽江\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/bdb6f791cc812b58d15493277c7733ef/1040g2sg319298qgeku705pf6h6519ed433unon0!nd_dft_wlteh_webp_3\",\n        category: \"玉龙雪山攻略\"\n    },\n    {\n        id: 9,\n        title: \"玉龙雪山一日游\\uD83D\\uDCB0300➕一口价全包！太给力了\",\n        author: \"\\uD83C\\uDF51\",\n        content: \"\\uD83D\\uDE4B作为一名老管家，小伙伴们想要玉龙雪山一日游，建议至少提前两天预定，因为票真的很难抢。如果没有抢到票，可以考虑报个我们这样的一日游，纯玩团，6-8人小团，省心～，纯玩不购物，也没有隐形消费。\",\n        likes: 170,\n        comments: 132,\n        tags: [\n            \"玉龙雪山\",\n            \"一日游\",\n            \"丽江\",\n            \"云南\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/d61c16a5c201dcb660fd78e71a7ec22c/1040g2sg319298qgeku7g5pf6h6519ed432qig7g!nd_dft_wlteh_webp_3\",\n        category: \"玉龙雪山攻略\"\n    },\n    {\n        id: 10,\n        title: \"没人能拒绝今天的玉龙雪山！！！！ 太美了\",\n        author: \"野在山川\",\n        content: \"❄️【冬日玉龙雪山，冰川公园的绝美仙境】❄️，\\uD83C\\uDF1F冬天的玉龙雪山，简直就是人间仙境！\\uD83C\\uDFD4️ 冰川公园在白雪的覆盖下，仿佛披上了一层银装，美得让人窒息！\\uD83D\\uDE0D\",\n        likes: 881,\n        comments: 126,\n        tags: [\n            \"玉龙雪山\",\n            \"冰川公园\",\n            \"冬日仙境\",\n            \"丽江\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/0178f9d425f22a4bd0361d80ec402856/1040g2sg319298qgeku805pf6h6519ed4fdh9r3o!nd_dft_wlteh_webp_3\",\n        category: \"玉龙雪山攻略\"\n    },\n    // 大理古城相关攻略\n    {\n        id: 11,\n        title: \"大理古城一日游|citywalk图文路线攻略\",\n        author: \"卡比卡比\",\n        content: \"大理古城真的好看又好拍！远看有震撼的苍山做背景，近看有各种古建筑和文艺创意小店。用一天时间看了大理古城的几处经典古建筑，逛了文创街区，收获满满。特整理的图文路线攻略，希望能帮到大家。\",\n        likes: 5068,\n        comments: 26,\n        tags: [\n            \"大理古城\",\n            \"citywalk\",\n            \"路线攻略\",\n            \"云南\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/43dfbc86f69d2b1648b99676d227279f/1040g2sg31cel7nnq0k5g5npnb07g9flasnrilno!nd_dft_wlteh_webp_3\",\n        category: \"大理古城攻略\"\n    },\n    {\n        id: 12,\n        title: \"大理古城经典夜游路线（附详细路线图）\",\n        author: \"轻行心旅\",\n        content: \"来大理玩，建议白天外出去各个景点，比如苍山洱海喜洲等，夜游古城，才是更好的体验。首图已经标注清楚路线图，照着走就行啦。夜游路线：全程3～4公里，约逛2～3小时。\",\n        likes: 4583,\n        comments: 32,\n        tags: [\n            \"大理古城\",\n            \"夜游路线\",\n            \"路线图\",\n            \"大理\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/d9ec4366ffb2f0d9e2984fb3650e904a/1040g00831cel7nsrgm6g5npnb07g9flat841nq8!nd_dft_wlteh_webp_3\",\n        category: \"大理古城攻略\"\n    },\n    {\n        id: 13,\n        title: \"超级详细‼️大理古城一日逛吃攻略\",\n        author: \"十一mcc\",\n        content: '花一天沉浸式体验大理古城的烟火气与慢生活！\\uD83C\\uDF04，南城门很多旅游团都是在这里下车，可以拍经典\"大理\"城门打卡照✌️，床单厂艺术区这个是复古厂房改造的，现在是很多小众手作聚集地，很好逛！',\n        likes: 370,\n        comments: 1,\n        tags: [\n            \"大理古城\",\n            \"逛吃攻略\",\n            \"美食\",\n            \"大理\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/1242d1bbff494ba353922739a484e705/1040g2sg31cel7nn5gudg5npnb07g9flar810g68!nd_dft_wlteh_webp_3\",\n        category: \"大理古城攻略\"\n    },\n    {\n        id: 14,\n        title: \"\\uD83C\\uDFDE️云南大理古城\\uD83C\\uDFF0深度游攻略来啦\",\n        author: \"小许玩攻略\",\n        content: \"Hey小伙伴们～\\uD83D\\uDC4B 今天要带你们走进的，是彩云之南的瑰宝——大理古城！\\uD83C\\uDFF0 准备好和我一起，在古城墙下感受那份穿越时空的静谧与浪漫了吗？\\uD83D\\uDC95\",\n        likes: 7,\n        comments: 1,\n        tags: [\n            \"大理古城\",\n            \"深度游\",\n            \"云南\",\n            \"攻略\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/96d8f89a20157ed51bdc767768a736a8/1040g2sg31cel7ntg0mdg5npnb07g9fla6f4ql5g!nd_dft_wgth_webp_3\",\n        category: \"大理古城攻略\"\n    },\n    {\n        id: 15,\n        title: \"大理古城 每一帧都可以成为我的壁纸\",\n        author: \"萝卜君\",\n        content: \"**诗意大理，古城时光**，初临大理，漫步在大理古城的青石板路上，仿佛穿越了千年的时光。苍山洱海间，白墙黛瓦下，每一处风景都写满了故事。这里是南诏古国的都城，是茶马古道的起点，更是我心中的诗和远方！\",\n        likes: 10,\n        comments: 0,\n        tags: [\n            \"大理古城\",\n            \"诗意\",\n            \"南诏\",\n            \"茶马古道\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/38ba348ea6335ef238aa3c1755ad0d74/1040g00831cel7ntdgu6g5npnb07g9fla0i3vf30!nd_dft_wlteh_webp_3\",\n        category: \"大理古城攻略\"\n    },\n    // 丽江相关攻略\n    {\n        id: 16,\n        title: \"男朋友做的丽江路线~工科男的逻辑就是强\",\n        author: \"爱吃鱼的大脸猫\",\n        content: \"7-9月准备去丽江的注意啦！✔出发前一定要先看的丽江旅游攻略\\uD83E\\uDD7A男朋友熬夜做的！不废话全是干货～欢迎来抄作业✍（因为这样就可以和我一样闭眼跟着玩了哈哈）\",\n        likes: 7250,\n        comments: 243,\n        tags: [\n            \"丽江\",\n            \"旅游攻略\",\n            \"路线规划\",\n            \"云南\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/6040b5cf38bea3a422bab36545056a44/1040g2sg319298qgeku8g5pf6h6519ed4mifer80!nd_dft_wlteh_webp_3\",\n        category: \"丽江攻略\"\n    },\n    {\n        id: 17,\n        title: \"刚从丽江回来⛰总结出的九大必去景点\",\n        author: \"小\\uD83D\\uDC1F不营业\",\n        content: \"进入11月，玉龙雪山迎来了日照金山蕞佳观景期。很多游客因此慕名而来，整个行程下来，还是觉得这些景点蕞值得打卡。丽江古城在古城，可以在青石板的小道上溜达闲逛，也可以在客栈外面的藤椅上闭眼小憩。\",\n        likes: 182,\n        comments: 0,\n        tags: [\n            \"丽江\",\n            \"必去景点\",\n            \"玉龙雪山\",\n            \"古城\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/c6084358bcf2aed1959197217f11fa3b/1040g2sg319298qgeku905pf6h6519ed4ig7dl9g!nd_dft_wlteh_webp_3\",\n        category: \"丽江攻略\"\n    },\n    {\n        id: 18,\n        title: \"昆明-大理-丽江旅游攻略\",\n        author: \"鹿先森\",\n        content: \"\\uD83C\\uDF1F【云南11日游】昆明→大理→丽江→泸沽湖，人均3.5k玩到爽！超详细路线+避坑攻略\\uD83D\\uDC96，11天玩转昆明大理丽江泸沽湖，人均只花了3.5k！性价比炸裂\\uD83D\\uDCA5\",\n        likes: 1839,\n        comments: 31,\n        tags: [\n            \"昆明\",\n            \"大理\",\n            \"丽江\",\n            \"泸沽湖\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/d31a210bfd55b4e4e13ceff7507f1e70/1040g2sg319298qgeku9g5pf6h6519ed42s2bkjo!nd_dft_wlteh_webp_3\",\n        category: \"丽江攻略\"\n    },\n    {\n        id: 19,\n        title: \"在丽江 找到了旅居终极答案-千依山舍\",\n        author: \"茜茜\",\n        content: \"第一次到云南✅ 云南游攻略♥，惊喜~在丽江，我找到了理想山居的终极答案｜千依山舍，初次云南之行必看✅，新鲜云南攻略揭晓\\uD83E\\uDDD0，精心整理的新鲜云南指南，欢迎首次造访云南的朋友~。\",\n        likes: 660,\n        comments: 4,\n        tags: [\n            \"丽江\",\n            \"旅居\",\n            \"千依山舍\",\n            \"云南\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/c000a34253ea68d6ebf120ec3e0ed2ea/1040g2sg319298qgekua05pf6h6519ed4oduii38!nd_dft_wlteh_webp_3\",\n        category: \"丽江攻略\"\n    },\n    {\n        id: 20,\n        title: \"去丽江徒步不要只知道虎跳峡了！这儿更美\",\n        author: \"Amos富士人像\",\n        content: \"live 实况直出｜让心在蓝天与暴风间跳动，\\uD83D\\uDEB6路程15公里左右，爬升900米，必须装备：1～2升水、两步路app 、冲锋衣，可以当向dao，1-3人。摄影向岛。\",\n        likes: 794,\n        comments: 235,\n        tags: [\n            \"丽江\",\n            \"徒步\",\n            \"虎跳峡\",\n            \"户外\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/bdb6f791cc812b58d15493277c7733ef/1040g2sg319298qgeku705pf6h6519ed433unon0!nd_dft_wlteh_webp_3\",\n        category: \"丽江攻略\"\n    },\n    // 自驾游相关攻略\n    {\n        id: 21,\n        title: \"深圳-云南\\uD83D\\uDE977日候鸟过冬自驾游路线\\uD83D\\uDDFA️\",\n        author: \"小林旅行日记\",\n        content: \"即将到冬季，准备开启新的候鸟南移路线了走之前把存货分享一下。去年11月末将车托运到深圳，然后带着我的\\uD83D\\uDC31从深圳出发自驾前往西双版纳，共耗时7天（单程）。\",\n        likes: 657,\n        comments: 71,\n        tags: [\n            \"深圳\",\n            \"云南\",\n            \"自驾游\",\n            \"西双版纳\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/43dfbc86f69d2b1648b99676d227279f/1040g2sg31cel7nnq0k5g5npnb07g9flasnrilno!nd_dft_wlteh_webp_3\",\n        category: \"自驾游攻略\"\n    },\n    {\n        id: 22,\n        title: \"广东自驾游路线天花板G323\\uD83D\\uDE972天1夜旅游攻略\",\n        author: \"一亭一亭呀\",\n        content: \"广东版此生必驾绝美公路—G323国道，森林瀑布，满天繁星，人少景美性价比高，图片摄于2024年国庆节，个人纯干货线路分享：岭背镇➡️秤架乡善美康桥➡️龙潭角瀑布➡️天井山生态长廊西门。\",\n        likes: 1639,\n        comments: 221,\n        tags: [\n            \"广东\",\n            \"自驾游\",\n            \"G323国道\",\n            \"天井山\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/d9ec4366ffb2f0d9e2984fb3650e904a/1040g00831cel7nsrgm6g5npnb07g9flat841nq8!nd_dft_wlteh_webp_3\",\n        category: \"自驾游攻略\"\n    },\n    {\n        id: 23,\n        title: \"30岁一人一车7天自驾广西，花费1500，太爽辣\",\n        author: \"小K挖点车\",\n        content: \"谁说一个人就不能旅行了，作为P人，\\uD83D\\uDE36‍\\uD83C\\uDF2B️没有什么计划，一个念头闪过，只要有车在\\uD83D\\uDE99，说走就走的旅行直接出发。国庆7天6晚，快3000公里，总花费\\uD83D\\uDCB01500元左右。\",\n        likes: 60,\n        comments: 26,\n        tags: [\n            \"自驾游\",\n            \"广西\",\n            \"一人一车\",\n            \"说走就走\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/1242d1bbff494ba353922739a484e705/1040g2sg31cel7nn5gudg5npnb07g9flar810g68!nd_dft_wlteh_webp_3\",\n        category: \"自驾游攻略\"\n    },\n    {\n        id: 24,\n        title: \"广州-云南自驾  9.5天9晚 完美达成\",\n        author: \"杰伴童行\",\n        content: \"一家三口的广州出发云南自驾已回，9.5天，全程4462.2km，横跨5省，两人换着开，轻松拿下！路线：广州-南宁- 大理-丽江-香格里拉-攀枝花-安龙县-广州。\",\n        likes: 12,\n        comments: 7,\n        tags: [\n            \"广州\",\n            \"云南\",\n            \"自驾\",\n            \"大理丽江\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/96d8f89a20157ed51bdc767768a736a8/1040g2sg31cel7ntg0mdg5npnb07g9fla6f4ql5g!nd_dft_wgth_webp_3\",\n        category: \"自驾游攻略\"\n    },\n    {\n        id: 25,\n        title: \"\\uD83D\\uDD25广东自驾游封神路线：海边古村美食全攻略\",\n        author: \"鹏城出逃橘子\\uD83C\\uDF4A\",\n        content: \"\\uD83E\\uDD14今天五一第一天，大家出门了吗？是不是想出门，但又不知道去哪？知道去哪，但高铁\\uD83C\\uDFAB没买到？⭐看这里，深圳出发，广东周边自驾游，1-4小时+圈的自驾宝典来啦！\",\n        likes: 814,\n        comments: 86,\n        tags: [\n            \"广东\",\n            \"自驾游\",\n            \"深圳\",\n            \"周边游\"\n        ],\n        imageUrl: \"https://sns-webpic-qc.xhscdn.com/202508211123/38ba348ea6335ef238aa3c1755ad0d74/1040g00831cel7ntdgu6g5npnb07g9fla0i3vf30!nd_dft_wlteh_webp_3\",\n        category: \"自驾游攻略\"\n    }\n];\n//# sourceURL=[module]\n//# sourceMappingURL=data:application/json;charset=utf-8;base64,\n//# sourceURL=webpack-internal:///(ssr)/./data/xiaohongshuData.ts\n");

